</div></div><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script><script src="js/live-search.js"></script><script>function enlazarAccionesRepuestos(){document.querySelectorAll('.editar-repuesto').forEach(function(b){b.addEventListener('click',function(){['id','codigo','nombre','descripcion','minimo','precio'].forEach(function(c){var e=document.getElementById('editar-'+c);if(e)e.value=b.dataset[c]||'';});});});document.querySelectorAll('.movimiento-repuesto').forEach(function(b){b.addEventListener('click',function(){document.getElementById('movimiento-id').value=b.dataset.id;document.getElementById('movimiento-nombre').textContent=b.dataset.nombre;});});}enlazarAccionesRepuestos();document.addEventListener('ag:live-search-updated',enlazarAccionesRepuestos);</script></main></body></html>
